		echo '</table>';

		/* Where a difference comes from (BR-38): customer transactions with no entry to the debtors control account,
		entries to the control account that have no customer transaction, and postings made straight to the control
		account by other means (journals, bank entries) that never reach a customer balance. */
		$DebtorsAct = DB_escape_string($_SESSION['CompanyRecord']['debtorsact']);

		$SQL = "SELECT debtortrans.type,
						debtortrans.transno,
						debtortrans.debtorno,
						debtortrans.trandate,
						debtortrans.prd,
						(debtortrans.ovamount+debtortrans.ovgst+debtortrans.ovfreight+debtortrans.ovdiscount)/debtortrans.rate AS amount
				FROM debtortrans
				WHERE debtortrans.prd >= '" . $_POST['FromPeriod'] . "'
				AND debtortrans.prd <= '" . $_POST['ToPeriod'] . "'
				AND debtortrans.type IN (10, 11, 12, 15)
				AND NOT EXISTS (SELECT 1 FROM gltrans
								WHERE gltrans.type = debtortrans.type
								AND gltrans.typeno = debtortrans.transno
								AND gltrans.account = '" . $DebtorsAct . "')
				ORDER BY debtortrans.prd, debtortrans.type, debtortrans.transno";
		$Result = DB_query($SQL);
		echo '<br /><table border="1">
				<tr><th colspan="6">' . __('Customer transactions with no entry to the debtors control account') . '</th></tr>';
		if (DB_num_rows($Result) == 0) {
			echo '<tr><td colspan="6">' . __('None') . '</td></tr>';
		} else {
			echo '<tr><th>' . __('Type') . '</th><th>' . __('Number') . '</th><th>' . __('Customer') . '</th><th>' . __('Date') . '</th><th>' . __('Period') . '</th><th>' . __('Amount') . '</th></tr>';
			while ($MyRow = DB_fetch_array($Result)) {
				echo '<tr class="striped_row">
						<td>' . $MyRow['type'] . '</td>
