112	/* reasons a credit controller can choose for a status change. $Kind is 'stop', 'watch' or 'normal' */
113	function CreditReasonOptions($Kind, $Selected = '') {
114		switch ($Kind) {
115			case 'stop':
116				$Where = 'dissallowinvoices = 1';
117				break;
118			case 'watch':
119				$Where = 'dissallowinvoices = 2';
120				break;
121			default:
122				$Where = 'dissallowinvoices NOT IN (1, 2)';
123		}
124		$Result = DB_query("SELECT reasoncode, reasondescription FROM holdreasons WHERE " . $Where . " ORDER BY reasoncode");
125		$Options = '';
126		while ($MyRow = DB_fetch_array($Result)) {
127			$Options .= '<option ' . ($Selected == $MyRow['reasoncode'] ? 'selected="selected" ' : '') . 'value="' . $MyRow['reasoncode'] . '">' . htmlspecialchars($MyRow['reasondescription'], ENT_QUOTES, 'UTF-8') . '</option>';
128		}
129		return $Options;
130	}
